import csv
import json
import os
import sys
from collections import defaultdict
from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
OUT_DIR = "/app/submissions"
SOLUTION_PATH = os.path.join(OUT_DIR, "solution.csv")

def read_csv(path):
    with open(path, newline="") as f:
        return list(csv.DictReader(f))

def main():
    os.makedirs(OUT_DIR, exist_ok=True)

    with open(os.path.join(DATA_DIR, "config.json")) as f:
        config = json.load(f)

    providers = read_csv(os.path.join(DATA_DIR, "providers.csv"))
    slots = read_csv(os.path.join(DATA_DIR, "slots.csv"))
    appt_types = read_csv(os.path.join(DATA_DIR, "appointment_types.csv"))
    patients = read_csv(os.path.join(DATA_DIR, "patients.csv"))
    availability = read_csv(os.path.join(DATA_DIR, "provider_availability.csv"))

    provider_by_id = {p["provider_id"]: p for p in providers}
    slot_by_id = {s["slot_id"]: s for s in slots}
    slot_index = {s["slot_id"]: int(s["slot_index"]) for s in slots}
    slot_day = {s["slot_id"]: s["day"] for s in slots}
    slot_rc = {s["slot_id"]: int(s["in_person_room_capacity"]) for s in slots}
    slot_vc = {s["slot_id"]: int(s["telehealth_channel_capacity"]) for s in slots}
    slot_ec = {s["slot_id"]: int(s["exam_room_capacity"]) for s in slots}

    type_by_name = {t["appointment_type"]: t for t in appt_types}

    avail = {}
    for row in availability:
        avail[(row["provider_id"], row["slot_id"])] = int(row["available"]) == 1

    providers_by_specialty = defaultdict(list)
    for p in providers:
        providers_by_specialty[p["specialty"]].append(p["provider_id"])

    # Build candidate arcs
    arcs = []  # (patient_id, provider_id, slot_id, mode)
    patient_arcs = defaultdict(list)
    provider_slot_arcs = defaultdict(list)
    provider_day_arcs = defaultdict(list)
    slot_mode_arcs = defaultdict(list)
    slot_exam_arcs = []

    c_ip = float(config["in_person_mode_penalty"])
    c_th = float(config["telehealth_mode_penalty"])
    c_np = float(config["nonpreferred_provider_penalty"])
    c_wait = float(config["wait_penalty_per_slot_priority"])

    for pat in patients:
        pid = pat["patient_id"]
        specialty = pat["specialty_needed"]
        appt = pat["appointment_type"]
        tinfo = type_by_name[appt]
        requires_exam = int(tinfo["requires_exam_room"]) == 1
        tele_allowed_type = int(tinfo["telehealth_allowed"]) == 1
        earliest = int(slot_index[pat["earliest_slot"]])
        due = int(slot_index[pat["due_slot"]])
        priority = float(pat["priority_weight"])
        allowed_modes_raw = pat["allowed_modes"].strip()
        preferred = pat["preferred_provider"].strip()
        continuity = int(pat["continuity_required"]) == 1

        if allowed_modes_raw == "both":
            patient_modes = {"in_person", "telehealth"}
        elif allowed_modes_raw == "in_person":
            patient_modes = {"in_person"}
        elif allowed_modes_raw == "telehealth":
            patient_modes = {"telehealth"}
        else:
            raise ValueError(f"Unknown allowed_modes {allowed_modes_raw} for {pid}")

        if not tele_allowed_type:
            patient_modes.discard("telehealth")
        if not patient_modes:
            raise ValueError(f"No feasible mode for patient {pid}")

        candidate_providers = providers_by_specialty.get(specialty, [])
        if continuity and preferred:
            candidate_providers = [preferred]
        elif continuity:
            raise ValueError(f"Continuity required but no preferred provider for {pid}")

        for qid in candidate_providers:
            qinfo = provider_by_id[qid]
            for sid, sinfo in slot_by_id.items():
                sidx = int(sinfo["slot_index"])
                if sidx < earliest or sidx > due:
                    continue
                if not avail.get((qid, sid), 0):
                    continue
                for mode in patient_modes:
                    if mode == "telehealth" and int(qinfo["telehealth_enabled"]) != 1:
                        continue
                    if mode == "in_person" and int(qinfo["in_person_enabled"]) != 1:
                        continue
                    arc = (pid, qid, sid, mode)
                    arcs.append(arc)
                    patient_arcs[pid].append(arc)
                    provider_slot_arcs[(qid, sid)].append(arc)
                    provider_day_arcs[(qid, sinfo["day"])].append(arc)
                    slot_mode_arcs[(sid, mode)].append(arc)
                    if requires_exam:
                        slot_exam_arcs.append((sid, arc))

    # Feasibility quick check: every patient must have at least one arc
    for pat in patients:
        pid = pat["patient_id"]
        if not patient_arcs.get(pid):
            raise ValueError(f"No feasible arc for patient {pid}")

    model = Model("hybrid_telehealth_appointment_scheduling")
    model.setMinimize()
    model.setRealParam("limits/gap", float(config.get("solver_mip_gap", 0.0005)))

    env_time_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_time_limit is not None and env_time_limit.strip():
        model.setRealParam("limits/time", float(env_time_limit))

    x = {}
    for pid, qid, sid, mode in arcs:
        pat = next(p for p in patients if p["patient_id"] == pid)
        priority = float(pat["priority_weight"])
        sidx = int(slot_index[sid])
        preferred = pat["preferred_provider"].strip()
        mode_cost = c_ip if mode == "in_person" else c_th
        nonpref_cost = 0.0 if (preferred and qid == preferred) else c_np
        wait_cost = c_wait * priority * sidx
        obj = mode_cost + nonpref_cost + wait_cost
        var = model.addVar(vtype="B", name=f"x_{pid}_{qid}_{sid}_{mode}", obj=obj)
        x[(pid, qid, sid, mode)] = var

    # Patient exactly once
    for pat in patients:
        pid = pat["patient_id"]
        model.addCons(quicksum(x[arc] for arc in patient_arcs[pid]) == 1, name=f"patient_{pid}")

    # Provider at most one per slot
    for (qid, sid), arc_list in provider_slot_arcs.items():
        model.addCons(quicksum(x[arc] for arc in arc_list) <= 1, name=f"prov_slot_{qid}_{sid}")

    # Provider daily limit
    for qinfo in providers:
        qid = qinfo["provider_id"]
        limit = int(qinfo["daily_slot_limit"])
        for day in ["mon", "tue", "wed", "thu", "fri"]:
            arc_list = provider_day_arcs.get((qid, day), [])
            if arc_list:
                model.addCons(quicksum(x[arc] for arc in arc_list) <= limit, name=f"prov_day_{qid}_{day}")

    # Slot capacities
    for sinfo in slots:
        sid = sinfo["slot_id"]
        ip_arcs = slot_mode_arcs.get((sid, "in_person"), [])
        th_arcs = slot_mode_arcs.get((sid, "telehealth"), [])
        if ip_arcs:
            model.addCons(quicksum(x[arc] for arc in ip_arcs) <= slot_rc[sid], name=f"room_{sid}")
        if th_arcs:
            model.addCons(quicksum(x[arc] for arc in th_arcs) <= slot_vc[sid], name=f"channel_{sid}")
        exam_arcs = [arc for (exam_sid, arc) in slot_exam_arcs if exam_sid == sid]
        if exam_arcs:
            model.addCons(quicksum(x[arc] for arc in exam_arcs) <= slot_ec[sid], name=f"exam_{sid}")

    model.optimize()

    status = model.getStatus()
    if status not in ("optimal", "gap", "timelimit", "nodes", "bestsollimit"):
        # Still try to extract incumbent if available
        if model.getNsolns() == 0:
            raise RuntimeError(f"SCIP status {status} with no solution")

    solution = {}
    for pid, qid, sid, mode in arcs:
        val = model.getVal(x[(pid, qid, sid, mode)])
        if val is None:
            continue
        if val > 0.5:
            solution[pid] = (qid, sid, mode)

    # Validate and fill if any missing due to numerical issues
    missing = [p["patient_id"] for p in patients if p["patient_id"] not in solution]
    if missing:
        # Fallback: choose any arc with value closest to 1 for missing patients
        for pid in missing:
            best_arc = None
            best_val = -1.0
            for arc in patient_arcs[pid]:
                v = model.getVal(x[arc]) or 0.0
                if v > best_val:
                    best_val = v
                    best_arc = arc
            if best_arc is None:
                raise RuntimeError(f"No solution value for patient {pid}")
            solution[pid] = best_arc[1:]

    # Validate constraints in Python
    provider_slot_count = defaultdict(int)
    provider_day_count = defaultdict(int)
    slot_ip = defaultdict(int)
    slot_th = defaultdict(int)
    slot_exam = defaultdict(int)

    for pat in patients:
        pid = pat["patient_id"]
        qid, sid, mode = solution[pid]
        qinfo = provider_by_id[qid]
        sinfo = slot_by_id[sid]
        if qinfo["specialty"] != pat["specialty_needed"]:
            raise ValueError(f"Specialty mismatch for {pid}")
        if not avail.get((qid, sid), 0):
            raise ValueError(f"Provider {qid} unavailable at {sid} for {pid}")
        sidx = int(sinfo["slot_index"])
        if sidx < int(slot_index[pat["earliest_slot"]]) or sidx > int(slot_index[pat["due_slot"]]):
            raise ValueError(f"Window violation for {pid}")
        if mode not in {"in_person", "telehealth"}:
            raise ValueError(f"Bad mode for {pid}")
        if mode == "telehealth" and int(qinfo["telehealth_enabled"]) != 1:
            raise ValueError(f"Provider {qid} cannot telehealth for {pid}")
        if mode == "in_person" and int(qinfo["in_person_enabled"]) != 1:
            raise ValueError(f"Provider {qid} cannot in_person for {pid}")
        tinfo = type_by_name[pat["appointment_type"]]
        if mode == "telehealth" and int(tinfo["telehealth_allowed"]) != 1:
            raise ValueError(f"Type {pat['appointment_type']} does not allow telehealth for {pid}")
        allowed = pat["allowed_modes"].strip()
        if allowed == "in_person" and mode != "in_person":
            raise ValueError(f"Patient {pid} only allows in_person")
        if allowed == "telehealth" and mode != "telehealth":
            raise ValueError(f"Patient {pid} only allows telehealth")
        if int(pat["continuity_required"]) == 1 and qid != pat["preferred_provider"].strip():
            raise ValueError(f"Continuity violation for {pid}")

        provider_slot_count[(qid, sid)] += 1
        provider_day_count[(qid, sinfo["day"])] += 1
        if mode == "in_person":
            slot_ip[sid] += 1
        else:
            slot_th[sid] += 1
        if int(tinfo["requires_exam_room"]) == 1:
            slot_exam[sid] += 1

    for (qid, sid), cnt in provider_slot_count.items():
        if cnt > 1:
            raise ValueError(f"Provider {qid} has {cnt} patients in slot {sid}")
    for (qid, day), cnt in provider_day_count.items():
        limit = int(provider_by_id[qid]["daily_slot_limit"])
        if cnt > limit:
            raise ValueError(f"Provider {qid} exceeds daily limit on {day}")
    for sid, cnt in slot_ip.items():
        if cnt > slot_rc[sid]:
            raise ValueError(f"Room capacity exceeded at {sid}")
    for sid, cnt in slot_th.items():
        if cnt > slot_vc[sid]:
            raise ValueError(f"Channel capacity exceeded at {sid}")
    for sid, cnt in slot_exam.items():
        if cnt > slot_ec[sid]:
            raise ValueError(f"Exam room capacity exceeded at {sid}")

    with open(SOLUTION_PATH, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["patient_id", "provider_id", "slot_id", "mode"])
        for pat in patients:
            pid = pat["patient_id"]
            qid, sid, mode = solution[pid]
            writer.writerow([pid, qid, sid, mode])

    obj = model.getObjval() if model.getNsolns() > 0 else None
    print(f"SCIP status: {status}")
    print(f"Objective: {obj}")
    print(f"Solution written to {SOLUTION_PATH}")

if __name__ == "__main__":
    main()
